"""vectorops - simple vector operations."""

__version__ = "0.1.0"


def dotproduct(a, b):
    """Return the dot product of two equal-length lists of numbers.

    >>> dotproduct([1, 1], [0, 1])
    1
    """
    if len(a) != len(b):
        raise ValueError("vectors must have the same length")
    return sum(x * y for x, y in zip(a, b))

