def _kill_port(port):
    """Best-effort kill of any process listening on `port` (no pkill dependency)."""
    import socket
    # Find PIDs via /proc by scanning for the port in cmdline is unreliable;
    # instead use fuser if available, else skip (server may already be down).
    for tool in (["fuser", "-k", f"{port}/tcp"],):
        try:
            subprocess.run(tool, capture_output=True, timeout=5)
        except (FileNotFoundError, subprocess.TimeoutExpired):
            pass
    time.sleep(0.5)


def _start_server():
    """Start a detached pypi-server; return the Popen handle (or None if one is up)."""
    if _server_ready():
        return None  # an existing server is already serving
    _kill_port(PORT)
    proc = subprocess.Popen(
        ["pypi-server", "run", "-p", str(PORT), "-a", ".", "-P", ".", DIST_DIR],
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        stdin=subprocess.DEVNULL,
        start_new_session=True,
    )
    for _ in range(40):
        if _server_ready():
            return proc
        time.sleep(0.25)
    raise RuntimeError("pypi-server did not come up on port 8080")

